#!/usr/bin/env python3
"""Regenerate typed accessors from the shared presentation contract (no network)."""
from pathlib import Path
import json
import sys

def emit(path, text):
    if '--check' in sys.argv:
        if not path.exists() or path.read_text() != text:
            raise SystemExit(f'Generated file is stale: {path}')
    else:
        path.write_text(text)

ROOT=Path(__file__).resolve().parents[1]
contract=(ROOT/'python/src/maple_library/presentation.json').read_text()
data=json.loads(contract)
emit(ROOT/'java/src/main/resources/org/whitedoggy/maplelibrary/presentation.json',contract)
def camel(name):
    if name=='int':return 'intelligence'
    return name.split('_')[0]+''.join(x.capitalize() for x in name.split('_')[1:])
def pytype(kind):
    if kind.startswith('list:'):return 'tuple['+pytype(kind[5:])+', ...]'
    return {'text':'str','integer':'int','number':'Decimal','option':'OptionLine'}.get(kind,kind)
def jtype(kind):
    if kind.startswith('list:'):return 'List<'+jtype(kind[5:])+'>'
    return {'text':'String','integer':'Integer','number':'BigDecimal','option':'Presentation.OptionLine'}.get(kind,kind)
py=['# Generated by tools/generate_models.py. Edit presentation.json or the generator.','from __future__ import annotations','from decimal import Decimal','from .model import Source','from .presentation import Node, CharacterBase, OptionLine, Potential, Soul, potential, soul, stat_rows, preset, pets, Preset','']
ja=['package org.whitedoggy.maplelibrary;','import java.util.*;','import java.math.BigDecimal;','/** Typed immutable models. Generated by tools/generate_models.py. */','@SuppressWarnings("unchecked")','public final class Models {',' private Models() {}']
for name,fields in data['models'].items():
    py += [f'class {name}(Node):', '    __slots__ = ()']
    ja += [f' public static final class {name} extends FriendlyNode {{',f'  public {name}(EntityView detail) {{ super("{name}", detail); }}']
    for prop,spec in fields.items():
        typ=spec['type']
        py += ['    @property',f'    def {prop}(self) -> {pytype(typ)} | None:',f'        return self._get("{prop}")']
        ja += [f'  public {jtype(typ)} {camel(prop)}() {{ return ({jtype(typ)})readProperty("{prop}"); }}']
    if name in ('StatBlock','SymbolStats'):
        py += ['    def to_rows(self, *, include_zero=False):','        return stat_rows(self, include_zero)','    def to_text(self, *, include_zero=False):','        return "\\n".join(row["text"] for row in self.to_rows(include_zero=include_zero))']
        ja += ['  public List<Map<String,Object>> toRows() { return toRows(false); }','  public List<Map<String,Object>> toRows(boolean includeZero) { return Presentation.statRows(this,includeZero); }','  public String toText() { return toText(false); }','  public String toText(boolean includeZero) { return String.join("\\n",toRows(includeZero).stream().map(r->(String)r.get("text")).toList()); }']
    if name=='Pet':
        py += ['    @property','    def slot(self) -> int | None:','        return int(self._prefix.rstrip("_").split("_")[-1]) if self._prefix else None']
        ja += ['  public Pet(EntityView detail, String prefix) { super("Pet",detail,prefix); }', '  public Integer slot() { return prefix().isEmpty()?null:Integer.parseInt(prefix().replaceAll(".*_([1-3])_$", "$1")); }']
    if name=='NamedOption':
        py += ['    @property','    def text(self):','        return None if self.name is None or self.value is None else self.name+" "+self.value','    @property','    def effects(self):','        return () if self.text is None else OptionLine(self.text).effects']
        ja += ['  public String text() { return name()==null||value()==null?null:name()+" "+value(); }','  public List<OptionDecoder.Option> effects() { return text()==null?List.of():OptionDecoder.decode(text()); }']
    if name=='Item':
        py += ['    @property','    def potential(self) -> Potential | None:','        return potential(self)','    @property','    def additional_potential(self) -> Potential | None:','        return potential(self, "additional_potential_option")','    @property','    def soul(self) -> Soul | None:','        return soul(self)']
        ja += ['  public Presentation.Potential potential() { return Presentation.potential(this,"potential_option"); }','  public Presentation.Potential additionalPotential() { return Presentation.potential(this,"additional_potential_option"); }','  public Presentation.Soul soul() { return Presentation.soul(this); }']
    if 'text' in fields:
        py += ['    @property','    def effects(self):','        return () if self.text is None else OptionLine(self.text).effects']
        ja += ['  public List<OptionDecoder.Option> effects() { return text()==null ? List.of() : OptionDecoder.decode(text()); }']
    if name in data['presets']:
        _,typ,shape=data['presets'][name]
        ret='Preset['+typ+']' if shape=='list' else typ+' | None'
        py += [f'    def preset(self, number: int) -> {ret}:','        return preset(self, number)']
        jt='Presentation.Preset<'+typ+'>' if shape=='list' else typ
        ja += [f'  public {jt} preset(int number) {{ return ({jt})Presentation.preset(this,number); }}']
    if name in ('Equipment','Symbols'):
        prop='slot' if name=='Equipment' else 'name'
        typ='Item' if name=='Equipment' else 'Symbol'
        py += [f'    def get(self, {prop}: str) -> {typ} | None:',f'        if self.items is None:','            from .raw import MapleError','            raise MapleError("FIELD_UNAVAILABLE")',f'        return next((item for item in self.items if item.{prop} == {prop}), None)']
        ja += [f'  public {typ} get(String {prop}) {{ if(items()==null) throw new MapleException("FIELD_UNAVAILABLE"); return items().stream().filter(x->Objects.equals(x.{prop}(),{prop})).findFirst().orElse(null); }}']
    if name=='Equipment':
        for prop,slot in [('weapon','무기'),('secondary','보조무기'),('emblem','엠블렘')]:
            py += ['    @property',f'    def {prop}(self) -> Item | None:',f'        return self.get("{slot}")']
            ja += [f'  public Item {prop}() {{ return get("{slot}"); }}']
    if name in data.get('extra_presets',{}):
        for prop,(_,typ,shape) in data['extra_presets'][name].items():
            method=prop[:-1]
            ret='Preset['+typ+']' if shape=='list' else typ+' | None'
            py += [f'    def {method}(self, number: int) -> {ret}:',f'        return preset(self, number, "{prop}")']
            jt='Presentation.Preset<'+typ+'>' if shape=='list' else typ
            ja += [f'  public {jt} {camel(method)}(int number) {{ return ({jt})Presentation.preset(this,number,"{prop}"); }}']
    if name=='Pets':
        for prop,shared in [('items',False),('shared',True)]:
            py += ['    @property',f'    def {prop}(self) -> tuple[Pet, ...] | None:',f'        return pets(self, {shared})']
            ja += [f'  public List<Pet> {prop}() {{ return Presentation.pets(this,{str(shared).lower()}); }}']
    if name=='HyperStats':
        py += ['    @property','    def items(self) -> tuple[HyperStat, ...] | None:','        from .raw import MapleError','        if self.current_preset_number is None: raise MapleError("FIELD_UNAVAILABLE")','        return self.preset(self.current_preset_number).items']
        ja += ['  public List<HyperStat> items() { if(currentPresetNumber()==null)throw new MapleException("FIELD_UNAVAILABLE"); return preset(currentPresetNumber()).items(); }']
    if name=='ReportedStats':
        py += ['    def get(self, name: str) -> StatEntry | None:','        from .raw import MapleError','        if self.entries is None: raise MapleError("FIELD_UNAVAILABLE")','        return next((x for x in self.entries if x.name == name), None)']
        ja += ['  public StatEntry get(String name) { if(entries()==null)throw new MapleException("FIELD_UNAVAILABLE"); return entries().stream().filter(x->Objects.equals(x.name(),name)).findFirst().orElse(null); }']
    py += ['']
    ja += [' }']
ja+=[' static FriendlyNode create(String type, EntityView detail) { return switch(type) {']
for name in data['models']:ja += [f' case "{name}" -> new {name}(detail);']
ja+=[' default -> throw new MapleException("INVALID_REQUEST"); }; }','}']
groups={'Union':{'basic':'UNION_BASIC','raider':'UNION_RAIDER','artifact':'UNION_ARTIFACT','champion':'UNION_CHAMPION'},'SkillGroup':{'zero':'SKILL_0','hyper_passive':'SKILL_HYPER_PASSIVE','hyper_active':'SKILL_HYPER_ACTIVE','fifth':'SKILL_5','sixth':'SKILL_6'},'Hexa':{'cores':'HEXA_CORES','stats':'HEXA_STATS'},'SpecialRings':{'exchange':'RING_EXCHANGE','reserve':'RING_RESERVE'}}
py += ['from .presentation import SourceGroup']
for group,members in groups.items():
    py += [f'class {group}(SourceGroup):','    __slots__ = ()','    def __init__(self, character):',f'        super().__init__(character, {members!r})']
    for prop,source in members.items():
        py += ['    @property',f'    def {prop}(self) -> {data["sources"][source][1]}:',f'        return self._character.source(Source.{source})']
py+=['class Character(CharacterBase):','    __slots__ = ()']
for prop,group in [('union','Union'),('skills','SkillGroup'),('hexa','Hexa'),('special_rings','SpecialRings')]:
    py+=['    @property',f'    def {prop}(self) -> {group}:',f'        return {group}(self)']
for prop,typ in [('name','str'),('job','str'),('world','str'),('level','int')]:
    py+=['    @property',f'    def {prop}(self) -> {typ} | None:',f'        return self.basic.{prop}']
for source,(prop,kind) in data['sources'].items():
    py+=['    @property',f'    def {prop}(self) -> {kind}:',f'        return self.source(Source.{source})']
emit(ROOT/'python/src/maple_library/friendly.py','\n'.join(py)+'\n')
emit(ROOT/'java/src/main/java/org/whitedoggy/maplelibrary/Models.java','\n'.join(ja)+'\n')
# Character facade, separate public type so user imports stay short.
ja=['package org.whitedoggy.maplelibrary;','import java.util.*;','/** Convenient, network-free access to a collected sheet. */','public record Character(CharacterSheet sheet) {',' public Character { Objects.requireNonNull(sheet); }',' public FriendlyNode source(Source source) { var info=Presentation.SOURCES.get(source.name()); if(info==null)throw new MapleException("INVALID_REQUEST"); return Models.create(info.get(1),sheet.document(source).view()); }']
for source,(prop,kind) in data['sources'].items():ja += [f' public Models.{kind} {camel(prop)}() {{ return (Models.{kind})source(Source.{source}); }}']
for group,members in {'Union':{'basic':'UNION_BASIC','raider':'UNION_RAIDER','artifact':'UNION_ARTIFACT','champion':'UNION_CHAMPION'},'Skills':{'zero':'SKILL_0','hyperPassive':'SKILL_HYPER_PASSIVE','hyperActive':'SKILL_HYPER_ACTIVE','fifth':'SKILL_5','sixth':'SKILL_6'},'Hexa':{'cores':'HEXA_CORES','stats':'HEXA_STATS'},'SpecialRings':{'exchange':'RING_EXCHANGE','reserve':'RING_RESERVE'}}.items():
    method=group[0].lower()+group[1:]
    ja += [f' public {group} {method}() {{ return new {group}(this); }}',f' public record {group}(Character character) {{']
    for prop,s in members.items():ja += [f'  public Models.{data["sources"][s][1]} {prop}() {{ return character.{camel(data["sources"][s][0])}(); }}']
    view_pairs=[]
    for prop,source in members.items():
        key=''.join('_'+c.lower() if c.isupper() else c for c in prop)
        view_pairs += [f'"{key}"',f'Presentation.sourceView(character,Source.{source})']
    ja += [f'  public Map<String,Object> toView() {{ return Presentation.map({",".join(view_pairs)}); }}','  public String toJson() { return Presentation.toJson(toView()); }',' }']
ja += [' public String name() { return basic().name(); }',' public Integer level() { return basic().level(); }',' public String job() { return basic().job(); }',' public String world() { return basic().world(); }']
ja += [' public Map<String,Object> toView() { return Presentation.characterView(this); }',' public String toJson() { return Presentation.toJson(toView()); }','}']
import re
emit(ROOT/'java/src/main/java/org/whitedoggy/maplelibrary/MapleCharacter.java',re.sub(r'\bCharacter\b', 'MapleCharacter', '\n'.join(ja)+'\n'))
